    summary: "通过一系列 if-else 规则对样本进行划分。",
    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>把决策树想象成一场“20 个问题”游戏：一开始所有样本混在根节点，
      算法挑一个最能区分它们的特征提问（如“花瓣长度 &gt; 2.5cm？”），把样本分成左右两堆；
      然后对每一堆<b>递归重复</b>同样的事，直到某堆里几乎只剩下同一类、或达到停止条件，就把它变成叶子节点。
      预测一个新样本时，只需从根节点顺着条件一路走到某个叶子，该叶子的多数类别就是预测结果。
      整棵树等价于一组 <b>if-else 规则</b>，这也是它高度可解释的原因。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>熵（Entropy）</b>：衡量一组样本的混乱程度，各类别比例越平均则熵越大（二分类五五开时最大为 1），越纯则越接近 0。</li>
        <li><b>信息增益</b> = 划分前的熵 − 划分后各子集按样本数加权平均的熵。<b>增益越大</b>说明这次划分让数据“变纯”得越多，优先选它。</li>
        <li><b>基尼不纯度</b>：另一种纯度度量，表示随机抽两个样本类别不一致的概率；值越小越纯。它不做对数运算，<b>计算更快</b>，是 sklearn 的默认值。</li>
        <li>两者在多数场景下结果接近：基尼偏向于把多数类分得更干净，信息增益对取值多的特征略有偏好（可用增益率修正）。</li>
      </ul>
      <h3>树的构建过程</h3>
      <ul>
        <li>对每个候选特征，穷举可能的<b>分裂阈值</b>，计算划分后的不纯度下降。</li>
        <li>选择使不纯度下降最多的（特征, 阈值）组合作为本节点的分裂规则。</li>
        <li>对左右子集递归分裂，直到满足停止条件：节点已纯、样本数少于 <code>min_samples_split</code>、深度达到 <code>max_depth</code>、或增益小于阈值。</li>
        <li>叶子节点的预测值 = 该叶子中训练样本的<b>多数类别</b>（分类）或<b>均值</b>（回归）。</li>
      </ul>
      <h3>过拟合问题</h3>
      <p>如果不加限制，树会一直分裂到每个叶子只剩一个样本——训练集准确率 100%，但对新数据一塌糊涂。
      本质原因是<b>方差过高</b>：树对训练集的噪声也照单全收。此外决策边界是<b>轴平行</b>的（只能画横平竖直的线），
      对斜向边界的表达效率低；且对样本扰动敏感，训练集微调可能导致整棵树结构大变。</p>
      <h3>剪枝策略</h3>
      <ul>
        <li><b>预剪枝（更好用）</b>：在生长过程中提前设限——<code>max_depth</code> 限深度、<code>min_samples_split</code> 限分裂所需最小样本数、<code>min_samples_leaf</code> 限叶子最小样本数、<code>max_features</code> 限制候选特征数。<b>简单高效，首选这种方式。</b></li>
        <li><b>后剪枝</b>：先让树长满，再自底向上把收益不高的子树替换成叶子。scikit-learn 通过 <code>ccp_alpha</code>（代价复杂度剪枝 / 最小代价复杂度）支持，alpha 越大剪得越狠。</li>
        <li><b>集成替代</b>：单棵树方差高，用 Bagging（随机森林）或 Boosting 把多棵树组合起来，通常比反复剪枝更有效。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>DecisionTreeClassifier</code>（分类）、<code>DecisionTreeRegressor</code>（回归）；
      可用 <code>export_text</code> 打印规则、<code>plot_tree</code> 画出树结构，非常适合教学演示。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>max_depth</b>：最有效的防过拟合旋钮。先从 3~5 试起，配合验证曲线找拐点。</li>
        <li><b>min_samples_leaf</b>：设成 5、10、20 之类的值比单纯限深度更灵活，样本大时可相应调大。</li>
        <li><b>criterion</b>：<code>"gini"</code>（默认，快）或 <code>"entropy"</code>/<code>"log_loss"</code>；差别通常不大。</li>
        <li><b>class_weight="balanced"</b>：类别不平衡时的第一选择。</li>
        <li>建议固定 <code>random_state</code>，否则每次训练结构可能不同，难以复现。</li>
        <li><b>不要指望它外推</b>：回归树预测的是叶子内训练值的均值，无法预测超出历史范围的数值。</li>
      </ul>
    `,
