    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>二维平面上有红蓝两类点，能分开它们的直线有无数条。
      普通分类器随便挑一条；SVM 偏要挑那条<b>离两边都最远</b>的——它把直线两侧各平行推一条“边界线”，
      直到各自碰到最近的样本点（这些点就是<b>支持向量</b>），然后最大化两条边界线之间的<b>间隔（margin）</b>。
      这样做的好处是：新样本即使稍有偏移，也大概率落在正确一侧，泛化更有保障。
      而且最终模型<b>只由支持向量决定</b>——删掉其它所有点，决策边界完全不变，这也是它名字的由来。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>超平面</b>：在 d 维空间中，决策边界是 d−1 维的平面（二维里是直线、三维里是平面），写作 w·x + b = 0。w 是法向量（决定朝向），b 是偏置（决定位置）。</li>
        <li><b>间隔</b>：两类支持向量到超平面的距离之和，等于 2/‖w‖。因此<b>最大化间隔 ⇔ 最小化 ‖w‖</b>，这就是硬间隔 SVM 的优化目标。</li>
        <li><b>软间隔与松弛变量 ξ</b>：允许少量样本越界或落在间隔内，目标改为「最小化 ‖w‖²/2 + C·Σξ」。C 是惩罚系数：<b>C 大</b>→不容忍误分（间隔窄、易过拟合）；<b>C 小</b>→容忍更多误分（间隔宽、更平滑）。</li>
        <li><b>对偶与核函数</b>：优化可改写为只含样本间<b>内积</b>的形式，于是可以把内积整体替换成核函数 K(xᵢ, xⱼ)，等价于在（可能无穷维的）高维空间里做内积——这便是核技巧。</li>
      </ul>
      <h3>核技巧（Kernel Trick）</h3>
      <p>数据线性不可分时，与其显式地把特征升维（计算爆炸），不如<b>直接用一个函数算出高维空间里的内积</b>，
      永远不需要真的构造出那些新特征。这就是核技巧的精髓：以极低的代价获得高维甚至无穷维的表示能力。</p>
      <h3>常用核函数</h3>
      <ul>
        <li><b>linear（线性核）</b>：不做映射，就是原始空间的线性分类。特征数远大于样本数（如文本）时首选，快且不易过拟合。</li>
        <li><b>rbf / 高斯核</b>：最常用、默认选择，可拟合任意复杂边界。关键参数 <b>gamma</b> 控制单个样本的影响范围：gamma 大→影响小、边界弯曲复杂（易过拟合）；gamma 小→边界平滑（可能欠拟合）。</li>
        <li><b>poly（多项式核）</b>：degree 控制阶数（常用 2~3），阶数高时计算不稳定。</li>
        <li><b>sigmoid</b>：等价于一个两层神经网络，实际较少使用。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>SVC</code> / <code>SVR</code>（支持向量分类/回归，基于 libsvm，支持核函数）；
      <code>LinearSVC</code> / <code>LinearSVR</code>（专用线性实现，<b>大数据集快得多</b>）；
      <code>NuSVC</code>（用 ν 参数直接控制支持向量比例与误差上界）。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>必须标准化</b>：SVM 基于距离与内积，量纲不统一会让结果完全失真，且核函数对尺度极其敏感。</li>
        <li><b>C 与 gamma 是黄金组合</b>：几乎总是需要网格搜索，建议按对数网格取（如 C 取 0.1~1000，gamma 取 1e-4~10）。<b>gamma 过大是最常见的过拟合原因。</b></li>
        <li><b>先试线性核</b>：尤其高维稀疏数据（文本），LinearSVC 往往又快又好，别一上来就上 RBF。</li>
        <li><b>规模问题</b>：SVC 的训练复杂度大致在 O(n²)~O(n³)，样本过万会明显变慢——此时改用 LinearSVC 或 <code>SGDClassifier</code>。</li>
        <li><b>概率输出</b>：<code>probability=True</code> 会额外做五折交叉验证来校准，明显变慢，仅在需要 predict_proba 时开启。</li>
        <li><b>class_weight="balanced"</b>：类别不平衡时比手动调 C 更直接有效。</li>
      </ul>
    `,
