    summary: "把高维数据投影到低维，保留最大方差方向。",
    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>想象一团点云在三维空间里，形状像一根被压扁、斜着放的雪茄。
      虽然它占着三维空间，但真正的“长度”主要沿着雪茄的长轴——
      你只要沿着长轴拍一张照片，就能保留这团点云绝大部分的信息。
      PCA 做的就是这件事：<b>找到数据分布最长的那个方向</b>，把它作为第一根新坐标轴（第一主成分）；
      再在与它<b>垂直</b>的所有方向里找第二长的，作为第二主成分；依此类推。
      最后用前几根新轴重新表示数据，就完成了降维——
      本质是<b>换了一套坐标系</b>，并且这套坐标系是按“信息量”从大到小排好序的。</p>
      <h3>降维原理与步骤</h3>
      <ul>
        <li><b>中心化</b>：每个特征减去自身均值，使数据围绕原点分布。</li>
        <li><b>算协方差矩阵</b>：衡量两两特征之间“一起变化”的程度（见下）。</li>
        <li><b>特征值分解</b>：求出协方差矩阵的特征值与特征向量。</li>
        <li><b>排序取前 k 个</b>：特征值最大的 k 个特征向量就是前 k 个主成分方向。</li>
        <li><b>投影</b>：把原始数据投影到这 k 个方向上，得到 k 维的新表示。</li>
      </ul>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>协方差</b>：两个特征的协方差 = 它们各自与均值之差的<b>乘积的平均值</b>。同向变化时为正、反向为负、无关时接近 0。把两两协方差排成方阵即<b>协方差矩阵</b>，对角线是各特征自身的方差。</li>
        <li><b>特征值与特征向量</b>：若矩阵 A 作用于向量 v 后只是把它拉长了 λ 倍（Av = λv），则 v 是特征向量、λ 是特征值。在 PCA 里，<b>特征向量就是主成分的方向，特征值就是该方向上的方差大小</b>。</li>
        <li><b>方差解释率</b>：第 i 个主成分的解释率 = λᵢ / (λ₁ + λ₂ + … + λₙ)，表示它承载了原始数据百分之多少的信息。</li>
        <li><b>累计方差解释率</b>：前 k 个解释率之和。实践中常取<b>使累计解释率达到 90%~95% 的最小 k</b>。</li>
      </ul>
      <h3>可视化应用</h3>
      <ul>
        <li><b>高维数据散点图</b>：把几十上百维降到 2 维画出来，肉眼观察是否有天然分群、是否有离群点。这是最常用的探索性手段。</li>
        <li><b>碎石图（Scree Plot）</b>：横轴是主成分序号、纵轴是解释率（或特征值），用于选择保留几个主成分——找拐点。</li>
        <li><b>主成分散点图着色</b>：把前两个主成分画成散点图，按类别/簇标签着色，可直观看出类别是否可分。</li>
        <li>经典案例：把 784 维的手写数字图像降到 2 维可视化；把人脸图像压缩成“特征脸”（Eigenfaces）。</li>
      </ul>
      <h3>其它用处</h3>
      <ul>
        <li><b>去噪</b>：方差极小的主成分往往对应噪声，丢弃它们相当于滤波。</li>
        <li><b>提速与去冗余</b>：特征高度相关时，降维能显著减少后续模型的训练时间与过拟合风险。</li>
        <li><b>共线性缓解</b>：主成分两两正交（不相关），可直接喂给线性回归等对共线性敏感的模型。</li>
      </ul>
      <h3>局限</h3>
      <p>主成分是原始特征的<b>线性组合</b>，可解释性弱于原始特征（你不能说“主成分 1 就是年龄”）；
      它是<b>无监督</b>的，降维时完全不看标签，因此保留的大方差方向未必是对分类最有用的方向（这时可用 LDA）；
      另外它只能捕捉线性结构，对环形、瑞士卷这类非线性流形无效（需 Kernel PCA、t-SNE 或 UMAP）。</p>
      <h3>scikit-learn 实现</h3>
      <p><code>PCA</code>（主实现，<code>n_components</code> 可设为整数或 0~1 的解释率，如 0.95）；
      <code>IncrementalPCA</code>（大数据分批）；<code>KernelPCA</code>（非线性）；
      <code>TruncatedSVD</code>（稀疏矩阵，文本常用）。
      属性：<code>explained_variance_ratio_</code>（各主成分解释率）、<code>components_</code>（主成分方向）、<code>transform()</code> 投影。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>必须先标准化</b>：PCA 按方差大小排序，若不标准化，量纲大的特征（如“收入”以元计）会完全主导主成分。<code>StandardScaler</code> 是标配（除非所有特征本来同量纲，如图像像素）。</li>
        <li><b>n_components</b>：可视化固定取 2 或 3；用于预处理时取 <code>0.95</code> 让 sklearn 自动决定保留多少个。</li>
        <li><b>用碎石图确认</b>：别盲目取 2 维，先看累计解释率是否够高——若前两个主成分只解释了 30%，那张散点图基本没有意义。</li>
        <li><b>不要在全量数据上 fit</b>：正确做法是只在<b>训练集</b>上 fit PCA 再 transform 测试集（或用 <code>Pipeline</code> 封装），否则会泄漏测试集信息。</li>
        <li><b>降维后特征失去含义</b>：若业务上需要可解释性，应优先做特征选择而非 PCA。</li>
        <li><b>类别不平衡/异常值</b>：离群点会严重扭曲主成分方向，建议先做异常检测或改用稳健的 PCA 变体。</li>
      </ul>
    `,
