    body: `
      <h3>三种状态</h3>
      <ul>
        <li><b>欠拟合</b>：模型太简单，连训练数据都学不好（高偏差）。</li>
        <li><b>过拟合</b>：模型太复杂，把训练噪声也记住了，新数据上表现差（高方差）。</li>
        <li><b>良好拟合</b>：训练与测试误差都低且接近。</li>
      </ul>
      <h3>如何检测：对比训练误差与验证误差</h3>
      <p>把同一个模型分别算训练集误差与验证集误差，两者的“水平”和“差距”就是诊断依据：</p>
      <ul>
        <li><b>欠拟合</b>：训练误差高，验证误差也高，且两者接近 → 模型根本没学会。</li>
        <li><b>过拟合</b>：训练误差很低，验证误差明显更高，差距很大 → 模型记住了噪声。</li>
        <li><b>良好拟合</b>：两者都低，且差距很小。</li>
      </ul>
      <p>更直观的做法是画学习曲线：训练/验证误差随训练轮数或模型复杂度变化的曲线。
      当验证误差开始回升而训练误差仍在下降时，就是过拟合的拐点，也是“早停”的最佳时机。</p>
      <h3>解决方案</h3>
      <ul>
        <li><b>更多数据</b>：最直接有效；数据不足时可用数据增强（图像翻转、裁剪、加噪等）扩充。</li>
        <li><b>正则化</b>：L1 正则产生稀疏解、可做特征选择；L2 正则压小权重、显著提升稳定性；线性模型与神经网络都适用。</li>
        <li><b>简化模型</b>：减少神经网络层数或神经元数、降低决策树深度、减小多项式次数。</li>
        <li><b>Dropout</b>：训练时随机丢弃一部分神经元，强迫网络不依赖个别特征，等价于一种集成。</li>
        <li><b>早停（Early Stopping）</b>：验证误差不再下降就停止训练，防止继续“背答案”。</li>
        <li><b>集成学习</b>：Bagging 类方法（如随机森林）可显著降低方差。</li>
        <li><b>反向操作（治欠拟合）</b>：增加特征或模型复杂度、减弱正则、延长训练时间。</li>
      </ul>
    `,
