    summary: "线性回归、岭回归、Lasso 的差异与选型指南。",
    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>三者都在拟合同一条线性关系，区别只在<b>如何惩罚过大的系数</b>。
      可以把它们想象成在同一个碗底找最低点，但地面被划了不同形状的“禁区”：</p>
      <ul>
        <li><b>线性回归</b>：毫无限制，碗里随便滚，找到最贴合训练数据的点。</li>
        <li><b>岭回归（L2）</b>：禁区是个圆形——它要求所有系数<b>整体变小</b>，但不强迫任何一个变成 0，系数被“均匀压缩”。</li>
        <li><b>Lasso（L1）</b>：禁区是个菱形（带尖角）——最优点常常落在尖角上，于是<b>部分系数被直接压成 0</b>，等于自动做了特征选择。</li>
      </ul>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>线性回归</b>：最小化预测值与真实值之差的平方和（即 MSE）。</li>
        <li><b>岭回归</b>：在 MSE 之上，加上「λ × 所有系数的平方和」（L2 范数的平方）。惩罚随系数平方增长，大系数被重点打压，但永不归零。</li>
        <li><b>Lasso</b>：在 MSE 之上，加上「λ × 所有系数的绝对值之和」（L1 范数）。绝对值在 0 处有折点，因此能产生<b>稀疏解</b>。</li>
        <li><b>ElasticNet</b>：L1 与 L2 按比例的加权组合，兼顾稀疏性与稳定性。</li>
      </ul>
      <h3>为什么需要正则化</h3>
      <p>当特征相关性强（多重共线性）或特征数接近样本数时，普通线性回归的系数会被放大到极不稳定——换一批训练数据，系数就剧烈变化。
      正则化用“牺牲一点训练集拟合度”换取“系数稳定、泛化更好”，这正是<b>偏差-方差权衡</b>的直接体现。</p>
      <h3>选型指南</h3>
      <ul>
        <li>特征少、样本多、无明显共线性 → <b>LinearRegression</b>。</li>
        <li>特征间高度相关、只想稳住系数 → <b>Ridge</b>（最常用、最安全）。</li>
        <li>特征很多但相信只有少数有用、想自动筛选 → <b>Lasso</b>。</li>
        <li>特征很多且彼此相关、既要筛选又要稳定 → <b>ElasticNet</b>。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>LinearRegression</code>、<code>Ridge</code>、<code>Lasso</code>、<code>ElasticNet</code>；
      带交叉验证自动选 λ 的版本是 <code>RidgeCV</code> / <code>LassoCV</code> / <code>ElasticNetCV</code>（推荐优先用 CV 版）。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>必须先标准化</b>：正则化惩罚的是系数大小，若特征量纲不同（如“面积”与“房龄”），惩罚会不公平。<code>StandardScaler</code> 是标配，配合 <code>Pipeline</code> 使用。</li>
        <li><b>alpha / λ</b>：越大惩罚越重、模型越简单。用 <code>RidgeCV(alphas=np.logspace(-3, 3, 50))</code> 这类对数网格搜索。</li>
        <li><b>Lasso 的 alpha 偏大</b>会把所有系数压成 0，得到常数预测——出现这种情况先调小 alpha。</li>
        <li><b>ElasticNet 的 l1_ratio</b>：0 等价于 Ridge，1 等价于 Lasso，一般从 0.5 起步，或把它一起放进网格搜索。</li>
        <li>检查 <code>coef_</code>：Lasso 中被压成 0 的特征就是它认为“不重要”的特征，可直接解读为特征选择结果。</li>
      </ul>
    `,
