    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>想象三个人各自独立猜一筐苹果的重量，取平均——结果往往比任何一个人更准。
      Bagging（Bootstrap Aggregating）正是这个思路：从训练集<b>有放回地随机抽样</b>出多份子数据集，
      每份独立训练一棵树，最后分类用<b>多数投票</b>、回归用<b>平均</b>。
      因为每棵树看到的数据略有不同，它们的错误是<b>不相关</b>的，平均后误差相互抵消——所以 Bagging 主要作用是<b>降低方差</b>。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>Bootstrap 抽样</b>：从 n 个样本中有放回地抽 n 次，每个样本被抽中的概率为 1−(1−1/n)ⁿ，
        当 n 较大时约为 <b>63.2%</b>，故每棵树平均只用了约三分之二的样本。</li>
        <li><b>聚合预测</b>：设共训练 B 棵树，第 b 棵树的预测为 h_b(x)。
        <b>分类</b>取多数投票：argmax(各类别得票数)；
        <b>回归</b>取算术平均：ĝ(x) = (1/B) · Σ h_b(x)。</li>
        <li><b>为什么能降方差</b>：若 B 棵树的误差彼此独立、单棵方差为 σ²，则平均后方差约为 σ²/B（相关性越低效果越接近）。
        现实中树之间存在相关性，所以收益会打折——这正是随机森林要再引入<b>随机特征子集</b>的原因。</li>
      </ul>
      <h3>Bootstrap 抽样</h3>
      <p>每棵树抽 n 个样本（有放回，n = 原训练集大小），因此约 36.8% 的样本不会被抽到，
      这部分称为<b>袋外样本（OOB）</b>，可直接当作验证集使用（<code>oob_score=True</code>），无需额外划分数据。</p>
      <h3>随机森林详解</h3>
      <p>随机森林 = Bagging + <b>随机特征子集</b>。普通 Bagging 的树在每次分裂时可以选全部特征，
      导致强特征（如“面积”）被所有树同时选中，树与树高度相似、错误也相似，集成收益有限。
      随机森林在每个节点只从随机抽出的 m 个特征里挑最优（分类默认 m = √p，回归默认 m = p/3），
      人为拉开树的差异，进一步降低相关性。</p>
      <h3>优势分析</h3>
      <ul>
        <li><b>抗过拟合</b>：单棵决策树极易过拟合，森林把它拉回来，通常可以直接用默认参数。</li>
        <li><b>几乎不用调参</b>：默认参数往往就有不错表现，是极佳的“第二基线”。</li>
        <li><b>能给出特征重要性</b>：<code>feature_importances_</code>（注意对高基数类别特征有偏）。</li>
        <li><b>可并行</b>：树之间互不影响，<code>n_jobs=-1</code> 可吃满所有 CPU。</li>
        <li>代价：模型体积大、预测比单棵树慢，且失去了单棵树的可解释性。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>BaggingClassifier</code> / <code>BaggingRegressor</code>（通用 Bagging，可套任意基模型）；
      <code>RandomForestClassifier</code> / <code>RandomForestRegressor</code>（随机森林）；
      <code>ExtraTreesClassifier</code>（极端随机树，分裂阈值也随机，更快、方差更低）。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>n_estimators</b>：树的数量，越多越稳、收益递减。一般 200~500 即可，过千收益很小但明显变慢。</li>
        <li><b>max_features</b>：最关键。默认（√p）通常合适；树相关性高时调小以增加多样性。</li>
        <li><b>max_depth / min_samples_leaf</b>：树太深会让方差回升。样本少时限制深度、增大叶节点最小样本数。</li>
        <li><b>class_weight</b>：类别不平衡时用 <code>"balanced"</code>。</li>
        <li>常见误区：<b>随机森林不适合外推</b>——它预测的是训练标签范围内的值，无法预测超出历史范围的趋势（回归需特别注意）。</li>
      </ul>
    `,
