    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>与 Bagging 的“众人独立投票”不同，Boosting 是<b>接力补课</b>：
      先训练一个弱模型，看看它<b>哪里错了</b>；下一个模型专门去啃这些错题——被前一个模型搞错的样本会被<b>提高权重</b>，
      逼迫后续模型重点关注。如此串行叠加几十上百轮，最后把所有弱模型<b>加权求和</b>。
      由于每一轮都在主动修正偏差，Boosting 主要作用是<b>降低偏差</b>（同时也会增大方差，所以更怕过拟合）。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>AdaBoost</b>：每轮训练后，按错误率计算该弱学习器的<b>话语权 α</b>（错误率越低 α 越大）；
        然后把分错样本的权重乘以 e^α 放大、分对的除以 e^α 缩小，再归一化。最终预测 = Σ(α × 弱学习器预测) 的符号。</li>
        <li><b>梯度提升（GBDT）</b>：把 Boosting 统一成<b>梯度下降</b>视角——每一轮不去改样本权重，
        而是让新树的拟合目标直接对准<b>损失函数对当前预测的负梯度</b>（即“残差”）。回归用平方损失时，负梯度正是真实值减预测值。</li>
        <li><b>XGBoost</b>：在 GBDT 目标上加<b>二阶泰勒展开</b>与<b>正则项</b>（叶子数 + 叶子权重的 L2），显式控制模型复杂度，因此泛化更好、更不易过拟合。</li>
      </ul>
      <h3>主流实现对比</h3>
      <ul>
        <li><b>AdaBoost</b>：最经典，理论优雅，但对噪声/异常值敏感（错分会不断被加权放大）。适合干净数据 + 弱分类器（如决策树桩）。</li>
        <li><b>GradientBoosting</b>：scikit-learn 内置，功能完整、速度一般，中小数据集够用。</li>
        <li><b>XGBoost</b>：工程优化的标杆，支持正则、缺失值自动处理、并行，长年霸榜各类竞赛。</li>
        <li><b>LightGBM</b>：微软出品，采用<b>直方图算法 + leaf-wise 生长</b>，速度快、内存省，大数据集首选。</li>
        <li><b>CatBoost</b>：Yandex 出品，对<b>类别特征</b>处理出色，几乎无需手动编码。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>AdaBoostClassifier</code> / <code>AdaBoostRegressor</code>；
      <code>GradientBoostingClassifier</code> / <code>GradientBoostingRegressor</code>；
      新版还有更快的 <code>HistGradientBoostingClassifier</code>（对标 LightGBM，支持缺失值与大数据）。
      XGBoost / LightGBM / CatBoost 需单独 <code>pip install</code>，但它们的 API 与 sklearn 一致（fit/predict）。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>learning_rate</b>：最关键。小学习率（0.01~0.1）+ 多棵树通常优于大学习率；调小学习率时应同步增大 n_estimators。</li>
        <li><b>n_estimators</b>：轮数太多会过拟合。务必配合<b>早停</b>（<code>n_iter_no_change</code> 或 XGBoost 的 <code>early_stopping_rounds</code>）。</li>
        <li><b>max_depth</b>：Boosting 的树要<b>浅</b>，通常 3~6。深树叠加极易过拟合，这是新手最常犯的错。</li>
        <li><b>subsample / colsample</b>：随机采样样本或特征（0.6~0.9），引入随机性、降低方差，是大数据的提速与抗过拟合手段。</li>
        <li>调参顺序建议：先定 learning_rate 与树深 → 用早停确定轮数 → 再微调采样比例与正则项。</li>
        <li>警惕<b>数据泄漏</b>：特征工程若有目标编码，必须放在交叉验证内部，否则 Boosting 会疯狂过拟合导致线上崩盘。</li>
      </ul>
    `,
