    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>层次聚类不要求你事先指定簇的数量，它输出的是一整棵<b>聚类树</b>。
      想象散点图上每个点各自成一簇，然后像搭积木一样，每次把<b>距离最近的两簇粘在一起</b>，
      反复这个过程直到全部并成一个大簇。把这些合并动作按相似度从高到低画出来，
      就是一棵倒挂的<b>树状图（Dendrogram）</b>：叶子在底部是单个样本，越往上合并的簇越大。
      想要几个簇，就在相应高度上横切一刀——切的位置越低簇越多、越细。</p>
      <h3>凝聚型 vs 分裂型</h3>
      <ul>
        <li><b>凝聚型（Agglomerative，自底向上）</b>：一开始每个样本各成一簇，反复合并最近的两簇。
        <b>实践中最常用</b>，scikit-learn 的 <code>AgglomerativeClustering</code> 就是这种。</li>
        <li><b>分裂型（Divisive，自顶向下）</b>：一开始所有样本是一整簇，反复把“最不像”的簇一分为二。
        理论上更准确，但每一步的划分选择空间极大、计算昂贵，实际很少直接用。</li>
      </ul>
      <h3>连接准则（如何定义“两簇之间的距离”）</h3>
      <ul>
        <li><b>单连接（Single Linkage）</b>：取两簇中<b>最近</b>一对样本的距离。能发现细长的链式簇，但容易形成“链条效应”把不同簇连成一串。</li>
        <li><b>全连接（Complete Linkage）</b>：取两簇中<b>最远</b>一对样本的距离。倾向产生大小相近的紧凑球形簇，对噪声较敏感。</li>
        <li><b>平均连接（Average Linkage）</b>：取所有样本对距离的<b>平均值</b>，是前两者的折中，表现最稳健。</li>
        <li><b>沃德法（Ward）</b>：合并后使簇内方差增加最小的两簇。倾向产生大小均衡的球形簇，<b>是 sklearn 的默认选择</b>，也是最常用的一项。</li>
      </ul>
      <h3>核心公式（文字说明）</h3>
      <p>设 A、B 是两个簇，d(x, y) 是两个样本之间的距离，则各连接准则定义的<b>簇间距离 D(A, B)</b> 为：</p>
      <ul>
        <li><b>单连接</b>：D(A, B) = <b>min</b> d(x, y)（取 A、B 中所有样本对里<b>最近</b>的一对）。</li>
        <li><b>全连接</b>：D(A, B) = <b>max</b> d(x, y)（取<b>最远</b>的一对）。</li>
        <li><b>平均连接</b>：D(A, B) = 所有样本对距离的<b>平均值</b>（共 |A|×|B| 对）。</li>
        <li><b>沃德法</b>：合并 A、B 引起的簇内方差增量 =
        <b>|A|·|B| / (|A|+|B|) × ‖质心_A − 质心_B‖²</b>；
        每次选择使该增量<b>最小</b>的两簇合并。可见它等价于“合并质心相距最近、且簇不太大的两簇”。</li>
      </ul>
      <p>每次合并后都要用上述公式<b>重新计算</b>新簇与其余所有簇的距离（这就是 Lance-Williams 更新的作用），
      这也是层次聚类复杂度偏高的原因之一。</p>
      <h3>树状图怎么读</h3>
      <ul>
        <li><b>纵轴是距离/相似度</b>：两条支线在越高的位置才汇合，说明两簇差别越大。</li>
        <li><b>横轴是样本</b>（顺序被重排过，无实际意义）。</li>
        <li><b>选簇数</b>：找纵轴上<b>最长的一段“空白”</b>（垂直线段最长、没有横向合并发生的地方）横切一刀，切下来的竖线条数就是簇数。</li>
        <li>不要只看树状图，配合轮廓系数一起判断更可靠。</li>
      </ul>
      <h3>优缺点与应用场景</h3>
      <ul>
        <li><b>优点</b>：无需预设 K、结果有层次结构可解释、可用树状图直观展示。</li>
        <li><b>缺点</b>：计算复杂度约 <b>O(n²)~O(n³)</b>、内存开销大，<b>只适合几千条以内的中小数据集</b>；且一旦合并就无法撤销（贪心）。</li>
        <li><b>适合</b>：物种分类、文档/基因层次归类、需要先看数据层次结构的探索性分析。</li>
      </ul>
      <h3>scikit-learn 实现</h3>
      <p><code>AgglomerativeClustering</code>（凝聚型，可指定 <code>n_clusters</code> 或 <code>distance_threshold</code>）；
      <code>FeatureAgglomeration</code>（用于特征聚类）；
      树状图需用 SciPy：<code>scipy.cluster.hierarchy.dendrogram(linkage(X, method="ward"))</code>。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>linkage</b>：默认 <code>"ward"</code>（要求欧氏距离）。想要非球形簇可试 <code>"average"</code> 或 <code>"single"</code>。</li>
        <li><b>n_clusters 与 distance_threshold 二选一</b>：设了距离阈值就不用指定簇数，由树自动决定切分。</li>
        <li><b>metric</b>：<code>"euclidean"</code>（默认）、<code>"l1"</code>、<code>"cosine"</code> 等；注意 ward 只支持欧氏。</li>
        <li><b>connectivity</b>：有邻接约束时（如图像相邻像素、地图上相邻区域）可传入连接矩阵，避免合并不相邻的样本。</li>
        <li>数据量大时先用采样或先用 K-Means 粗聚类再对簇中心做层次聚类。</li>
      </ul>
    `,
