    body: `
      <h3>算法原理图解（文字描述）</h3>
      <p>把数据想象成星空：密集的星团是簇，散落在空处的孤星是噪声。
      DBSCAN 的做法是——对每个点画一个半径为 <b>eps</b> 的圈，数圈里有多少邻居：</p>
      <ul>
        <li>圈里点数 ≥ <b>min_samples</b> → 这个点够“热闹”，称为<b>核心对象</b>，一个新簇从这里开始生长。</li>
        <li>圈里点数不够，但落在某个核心对象的圈内 → 称为<b>边界点</b>，归入该核心对象所在的簇（但它自己不能继续扩张）。</li>
        <li>既不是核心对象、也不在任何核心对象的圈内 → 判为<b>噪声点</b>（标签 −1），<b>不强行归入任何簇</b>。</li>
      </ul>
      <p>于是簇会沿着密集区域像“传染”一样不断向外扩张，直到遇到稀疏的空档就停止。</p>
      <h3>核心概念</h3>
      <ul>
        <li><b>eps（邻域半径）</b>：圈的半径。太小→几乎没有核心对象、大部分点变噪声；太大→所有点连成一整簇。</li>
        <li><b>min_samples</b>：成为核心对象所需的邻域内最少点数（含自身）。值越大越保守、抗噪越强。</li>
        <li><b>密度直达 / 密度可达 / 密度相连</b>：核心对象圈内的点是“直达”的；沿一串核心对象传递下去是“可达”的；由同一个核心对象发展出来的是“相连”的。一簇就是一个密度相连的极大集合。</li>
      </ul>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>eps-邻域</b>：N<sub>eps</sub>(p) = { q | 距离(p, q) ≤ eps }，即以 p 为圆心、eps 为半径的圈内所有点。</li>
        <li><b>核心对象判定</b>：当 <b>|N<sub>eps</sub>(p)| ≥ min_samples</b> 时，p 是核心对象。</li>
        <li><b>边界点</b>：p 本身不是核心对象，但存在某个核心对象 q 使得 p ∈ N<sub>eps</sub>(q)。</li>
        <li><b>噪声点</b>：既非核心对象、也不在任何核心对象邻域内的点，标签记为 <b>−1</b>。</li>
        <li><b>密度直达</b>：q 是核心对象且 p ∈ N<sub>eps</sub>(q) → p 从 q 密度直达。
        <b>密度可达</b>：存在一条 p₁→p₂→…→pₙ 的直达链把两点连起来。
        <b>一个簇</b> = 由某个核心对象出发、所有密度可达点构成的极大集合。</li>
      </ul>
      <p>整条定义里<b>没有任何一处需要指定簇的数量</b>——簇数完全是数据的密度分布决定的，这正是 DBSCAN 与 K-Means 最本质的区别。</p>
      <h3>相比 K-Means 的优势</h3>
      <ul>
        <li><b>不用指定簇数 K</b>：簇的数量由数据密度自动决定。</li>
        <li><b>能发现任意形状的簇</b>：K-Means 只能找球形簇，DBSCAN 能找出环形、月牙形、长条形等任意形状。</li>
        <li><b>自动识别并剔除噪声</b>：K-Means 会把离群点硬塞进某个簇并拉偏质心，DBSCAN 直接标为 −1。</li>
        <li><b>簇内密度不均时更合理</b>：不假设簇大小相近。</li>
      </ul>
      <h3>局限</h3>
      <p>当<b>簇的密度差异很大</b>时（一个很密一个很疏），一组 (eps, min_samples) 很难同时适用；
      高维数据下距离趋于同质，密度概念失效（维度灾难），建议先降维。
      另外它是<b>确定性</b>的（不像 K-Means 受随机初始化影响），这是优点也是好事。</p>
      <h3>scikit-learn 实现</h3>
      <p><code>DBSCAN</code>（主实现，标签 −1 表示噪声）；
      <code>OPTICS</code>（DBSCAN 的改进版，能处理<b>密度不均</b>的簇，无需精调 eps）；
      <code>HDBSCAN</code>（需额外安装 <code>hdbscan</code> 库，自动选簇、效果通常最好）。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>eps 是最关键的旋钮</b>：用 <b>k 距离图</b>选——计算每个点到第 k 个最近邻的距离并排序画图，取“拐点”处的距离作为 eps（k 常取 min_samples）。</li>
        <li><b>min_samples</b>：一般取 <b>2 × 特征维度</b> 起步；噪声多时调大。</li>
        <li><b>必须标准化</b>：eps 是个绝对距离，量纲不一致会让邻域完全失真。</li>
        <li>先诊断结果：若<b>几乎全是噪声</b>→ eps 太小或 min_samples 太大；若<b>只有一两个巨大的簇</b>→ eps 太大。</li>
        <li>密度差异明显的场景直接上 <code>OPTICS</code> 或 HDBSCAN，别死磕 DBSCAN 的参数。</li>
      </ul>
    `,
