    id: "dl-frameworks",
    title: "深度学习框架简介",
    icon: "⚙️",
    category: "advanced",
    summary: "TensorFlow/Keras 与 PyTorch 的对比与选型。",
    body: `
      <h3>为什么需要框架</h3>
      <p>手写反向传播和 GPU 算子不现实。深度学习框架替你做了三件事：
      <b>自动求导</b>（不用手推梯度）、<b>张量计算与 GPU 加速</b>、<b>现成的网络层与优化器</b>。
      你只需描述“网络长什么样”，剩下的交给框架。</p>
      <h3>算法原理图解（文字描述）</h3>
      <p>把框架想象成一条<b>带自动记录功能的计算流水线</b>：</p>
      <ul>
        <li><b>数据以张量（Tensor）形式流动</b>：标量是 0 维、向量是 1 维、矩阵是 2 维、彩色图像是 3 维（高×宽×通道），
        这些统一叫张量，可以在 CPU 或 GPU 上运算。</li>
        <li><b>前向传播</b>：张量从输入层一层层流过网络，每经过一个算子（矩阵乘、卷积、激活）就变换一次，最终得到预测值。</li>
        <li><b>记录计算过程</b>：框架在你前向计算的同时，把每一步操作偷偷记成一张<b>计算图</b>——这是后面能自动求导的前提。</li>
        <li><b>算损失并反向传播</b>：算出预测与答案的差距后，框架沿计算图<b>反向</b>应用链式法则，自动求出每个参数的梯度，你不需要手推任何导数。</li>
        <li><b>优化器更新参数</b>：把梯度交给优化器（SGD / Adam），它按学习率把参数往损失减小的方向挪一步。</li>
      </ul>
      <p>这五步循环若干轮（epoch），就是一次完整的训练。框架的价值在于：<b>第 3、4 步完全自动化</b>，
      你只需描述网络结构（第 2 步）和选择优化器（第 5 步）。</p>
      <h3>TensorFlow / Keras</h3>
      <ul>
        <li>TensorFlow 由 Google 开发，<b>Keras</b> 是它的官方高层 API（<code>tf.keras</code>），以“搭积木”著称。</li>
        <li><b>特点</b>：API 简洁（<code>model.add(Dense(64, activation="relu"))</code>）、文档与教程丰富、
        部署生态成熟（<b>TF Lite</b> 移动端、<b>TF Serving</b> 服务端、TensorFlow.js 浏览器端）。</li>
        <li>TensorFlow 2.x 默认启用 <b>Eager Execution</b>（即时执行），已像 PyTorch 一样可直接调试。</li>
        <li>适合：快速原型、教学入门、需要一条龙部署到生产/移动端的场景。</li>
      </ul>
      <h3>PyTorch</h3>
      <ul>
        <li>由 Meta（Facebook）开发，采用<b>动态计算图</b>，代码就是普通的 Python 控制流，调试体验最好。</li>
        <li><b>特点</b>：写法贴近 Python 直觉、<code>torch.nn.Module</code> 自定义灵活、
        与 NumPy 风格接近、生态有 <b>TorchVision / TorchText / HuggingFace Transformers</b>。</li>
        <li><b>当前学术界与研究领域的绝对主流</b>——新论文的实现绝大多数先出 PyTorch 版本。</li>
        <li>部署方面：TorchServe、以及 <b>ONNX</b> 格式可导出到其它推理引擎；2.0 起 <code>torch.compile</code> 大幅提速。</li>
      </ul>
      <h3>怎么选</h3>
      <ul>
        <li><b>完全零基础、想快速跑通第一个模型</b> → <b>Keras</b>，代码最少、报错最友好。</li>
        <li><b>打算读论文、做研究、复现最新模型（尤其 NLP/多模态）</b> → <b>PyTorch</b>，生态与资料压倒性优势。</li>
        <li><b>要部署到手机 App、嵌入式设备、浏览器</b> → <b>TensorFlow</b>（TF Lite 生态更成熟）。</li>
        <li><b>团队已有技术栈 / 公司规范</b> → 跟随团队，转换成本通常高于框架本身的差异。</li>
        <li>真心话：<b>两者能力高度重叠，纠结选型的时间不如直接开始写一个模型</b>。学会一个后，迁移到另一个只需一两周。</li>
      </ul>
      <h3>核心概念对照</h3>
      <ul>
        <li><b>张量</b>：PyTorch 的 <code>torch.Tensor</code> vs TensorFlow 的 <code>tf.Tensor</code>，都类似 NumPy 数组但能跑 GPU。</li>
        <li><b>自动求导</b>：PyTorch 用 <code>loss.backward()</code>；TensorFlow 用 <code>GradientTape</code> 上下文记录。</li>
        <li><b>定义模型</b>：PyTorch 继承 <code>nn.Module</code> 写 <code>forward</code>；Keras 用 <code>Sequential</code> 或函数式 API 堆叠层。</li>
        <li><b>训练循环</b>：Keras <code>model.fit()</code> 一行搞定；PyTorch 需手写 epoch 循环（更透明、也更灵活）。</li>
      </ul>
      <h3>Python 实现对照</h3>
      <p>同一个“两层全连接网络”在两框架下的写法（<code>pip install torch</code> / <code>pip install tensorflow</code>）：</p>
      <ul>
        <li><b>Keras</b>：<code>model = keras.Sequential([keras.layers.Dense(64, activation="relu"), keras.layers.Dense(10, activation="softmax")])</code>
        → <code>model.compile(optimizer="adam", loss="sparse_categorical_crossentropy")</code> → <code>model.fit(X, y, epochs=10)</code>。<b>三行搞定。</b></li>
        <li><b>PyTorch</b>：定义继承 <code>nn.Module</code> 的类并写 <code>forward()</code> → 选 <code>nn.CrossEntropyLoss()</code> 与 <code>torch.optim.Adam</code>
        → 手写 epoch 循环（<code>optimizer.zero_grad()</code> → <code>loss.backward()</code> → <code>optimizer.step()</code>）。<b>更啰嗦但完全透明。</b></li>
        <li>入门建议：先用 Keras 建立直觉，再用 PyTorch 重写一遍，就明白每一步在做什么了。</li>
      </ul>
      <h3>调参与实践注意事项</h3>
      <ul>
        <li><b>先跑通 CPU 版本</b>：确认逻辑正确再上 GPU，否则调试难度翻倍。</li>
        <li><b>固定随机种子</b>：深度学习结果有随机性，不设 seed 会导致无法复现。</li>
        <li><b>版本坑</b>：框架版本与 CUDA 驱动版本强耦合，安装前务必查官方兼容表。</li>
        <li><b>用预训练模型</b>：绝大多数场景不要从零训练，优先微调（fine-tune）现成的预训练权重。</li>
        <li>本网站是纯前端项目，运行深度学习代码需要本机 Python 环境并安装相应框架。</li>
      </ul>
    `,
