    body: `
      <h3>为什么需要 CNN</h3>
      <p>如果把一张 224×224 的彩色图直接拉平喂给普通全连接网络，输入就有 15 万个像素，
      第一层若接 1000 个神经元就产生上亿参数——不仅算不动，还极易过拟合。
      更关键的是：<b>全连接把像素的空间结构彻底破坏了</b>，而图像的关键信息恰恰在“相邻的像素构成什么形状”里。
      CNN 用<b>局部连接 + 权重共享</b>解决了这两点。</p>
      <h3>算法原理图解（文字描述）</h3>
      <p>把卷积想象成拿一个<b>小手电筒（卷积核 / filter）</b>在图片上从左到右、从上到下滑动。
      每停在一个位置，就把手电筒照到的一小块区域（如 3×3）与卷积核里的权重逐位相乘再求和，
      得到一个数字——这个数字衡量“这块区域是否含有该卷积核要找的特征”。
      扫完整张图就得到一张新的<b>特征图（Feature Map）</b>。
      不同的卷积核负责找不同特征：有的找竖直边缘、有的找水平边缘、有的找特定纹理。
      一个卷积核的权重在整张图上<b>共享</b>，所以参数量极少，且无论特征出现在图片哪个位置都能被找到（<b>平移不变性</b>）。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>卷积运算</b>：输出特征图上某个位置的值 =
        Σ（输入对应窗口内每个像素 × 卷积核对应位置的权重）+ 偏置。
        本质就是<b>局部窗口的加权求和</b>，权重即卷积核要检测的“模式”。</li>
        <li><b>输出尺寸</b>：若输入宽 W、卷积核大小 K、填充 P、步长 S，
        则输出宽 = <b>(W − K + 2P) / S + 1</b>（向下取整）。这是设置网络结构时必须反复验算的公式。</li>
        <li><b>参数量</b>：一个卷积层的参数 = <b>K × K × 输入通道数 × 卷积核个数</b>。
        注意它<b>只与卷积核大小有关，与输入图片尺寸无关</b>——这正是权重共享带来的巨大优势。</li>
        <li><b>感受野</b>：输出层一个像素能“看到”的输入区域大小。层数越深、卷积核叠加越多，感受野越大，语义层次越高。</li>
      </ul>
      <h3>三层结构各自的作用</h3>
      <ul>
        <li><b>卷积层（Convolution）</b>：提取局部特征（边缘→纹理→部件→物体）。层级越深，特征越抽象、语义越强。核心参数：卷积核大小、数量、步长 stride、填充 padding。</li>
        <li><b>池化层（Pooling）</b>：下采样压缩尺寸。最常用 <b>Max Pooling</b>（取窗口内最大值），作用是<b>减少计算量、扩大感受野、提供轻微平移鲁棒性</b>。它不含可学习参数。</li>
        <li><b>全连接层（FC）</b>：位于网络末端，把前面提取到的高级特征整合起来做最终分类/回归。现代网络常用 <b>全局平均池化</b>替代它以大幅减少参数。</li>
      </ul>
      <h3>经典网络结构</h3>
      <ul>
        <li><b>LeNet-5（1998，Yann LeCun）</b>：CNN 的开山之作，用于手写数字识别。结构是「卷积→池化→卷积→池化→全连接→输出」，仅约 6 万参数，是入门必读的原型。</li>
        <li><b>AlexNet（2012，ImageNet 冠军）</b>：深度学习的引爆点。首次大规模使用 <b>ReLU 激活</b>、<b>GPU 训练</b>、<b>Dropout</b> 与数据增强，8 层、6000 万参数，把 ImageNet 错误率大幅拉低，从此开启深度学习时代。</li>
        <li><b>后续演进</b>：VGG（统一用 3×3 小卷积堆叠）、GoogLeNet/Inception（多尺度并行）、<b>ResNet（残差连接解决深层退化，可上千层）</b>、MobileNet（移动端轻量）。</li>
      </ul>
      <h3>典型应用场景</h3>
      <p>图像分类、目标检测（YOLO、Faster R-CNN）、图像分割（U-Net）、人脸识别、医学影像分析。
      此外 CNN 也被用于文本（一维卷积）和时序信号。</p>
      <h3>实践实现方式</h3>
      <p>PyTorch：<code>torch.nn.Conv2d</code> / <code>MaxPool2d</code> / <code>torchvision.models.resnet18(pretrained=True)</code>；
      TensorFlow/Keras：<code>keras.layers.Conv2D</code> / <code>MaxPooling2D</code> / <code>keras.applications.ResNet50(weights="imagenet")</code>。
      入门练手推荐经典数据集 MNIST、CIFAR-10。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>优先用预训练 + 微调</b>：自己的数据少时，冻结 backbone 只训练最后的分类头，几乎总能胜过从零训练。</li>
        <li><b>卷积核用小的</b>：3×3 是主流，多个 3×3 堆叠比一个大核参数更少、非线性更强。</li>
        <li><b>数据增强</b>：随机翻转、裁剪、旋转、颜色抖动——对小数据集是性价比最高的提分手段。</li>
        <li><b>BatchNorm 几乎是标配</b>：加在卷积后、激活前，能加速收敛并稳定训练。</li>
        <li><b>输入尺寸</b>：多数预训练模型固定 224×224，需把图片缩放到对应尺寸并做相同的归一化（如 ImageNet 的均值/标准差）。</li>
        <li>过拟合时优先：加强数据增强 → 加 Dropout / 权重衰减 → 换更小的模型。</li>
      </ul>
    `,
