    summary: "处理带时间顺序的数据：平稳性、ARIMA 与滑动窗口。",
    body: `
      <h3>与普通数据的根本区别</h3>
      <p>普通表格数据假设样本<b>独立同分布</b>；时间序列的样本<b>按时间先后排列、彼此相关</b>——
      今天的销量和昨天的强相关。这带来两条铁律：</p>
      <ul>
        <li><b>不能随机打散</b>：随机划分训练/测试集会让模型用“未来”数据预测“过去”，造成严重的数据泄漏，测试分数虚高而线上崩盘。必须<b>按时间顺序切分</b>（或用 <code>TimeSeriesSplit</code>）。</li>
        <li><b>不能随便用普通交叉验证</b>：同上，要用时间序列专用的折法。</li>
      </ul>
      <h3>算法原理图解（文字描述）</h3>
      <p>把时间序列想成一张以<b>时间为横轴</b>的折线图，我们要做的无非三件事：</p>
      <ul>
        <li><b>看图拆零件</b>（分解）：一条波动向上的曲线，其实是三条线叠在一起——
        一条缓慢上升的<b>趋势线</b>、一圈规律起伏的<b>季节波动</b>、以及剩下毫无规律的<b>残差噪声</b>。
        把它们一层层剥开，就能分别建模与预测。</li>
        <li><b>检查是否稳定</b>（平稳性）：如果曲线的均值越走越高、波动幅度越来越大，
        那“过去的规律”就无法代表未来。要做的是把趋势去掉（<b>差分</b>：用今天的值减昨天的值），
        让剩下的一阶序列围绕一条水平线上下波动。</li>
        <li><b>用过去预测未来</b>（滑动窗口）：拿一把<b>长度为 n 的尺子</b>在折线上从左到右滑动，
        尺子里圈住的 n 个点作为特征 X，紧跟其后第 n+1 个点作为要预测的目标 y。
        尺子滑过整条曲线，就得到大量训练样本，于是可以用任意回归模型来做预测。</li>
      </ul>
      <h3>平稳性</h3>
      <p><b>平稳</b>指序列的统计性质（均值、方差、自相关结构）<b>不随时间变化</b>。
      大多数经典模型（如 ARIMA）都要求序列平稳——非平稳序列里，历史规律对未来没有参考价值。</p>
      <ul>
        <li><b>非平稳的典型表现</b>：有明显上升/下降趋势、方差逐渐变大、存在固定周期的季节性波动。</li>
        <li><b>检验方法</b>：<b>ADF 检验</b>（Augmented Dickey-Fuller，p 值 &lt; 0.05 通常认为平稳）、KPSS 检验（结论相反，可配合使用）。</li>
        <li><b>变平稳的手段</b>：<b>差分</b>（用后一期减前一期，一阶差分去趋势、二阶差分去曲率）、对数变换（稳定方差）、季节性差分（减去上一周期同一位置的值）。</li>
        <li>ARIMA 中的 <b>I</b>（Integrated）就是指“差分到平稳所需的阶数 d”。</li>
      </ul>
      <h3>趋势与季节性分解</h3>
      <p>一个序列通常可拆成三部分：<b>趋势（Trend，长期走向）+ 季节性（Seasonal，固定周期波动）+ 残差（Residual，剩余随机部分）</b>。
      经典分解有<b>加法模型</b>（三者相加，季节波动幅度恒定）与<b>乘法模型</b>（三者相乘，季节波动随趋势放大，更常见于经济数据）。
      Python 中用 <code>statsmodels.tsa.seasonal_decompose</code> 可一键分解并可视化，是做任何时序分析的第一步。</p>
      <h3>ARIMA 模型简介</h3>
      <p>ARIMA(p, d, q) 由三部分组成，名称即三个参数：</p>
      <ul>
        <li><b>AR(p) 自回归</b>：当前值由<b>过去 p 个时刻的值</b>线性组合而来（“今天和前几天差不多”）。</li>
        <li><b>I(d) 差分</b>：差分 d 次使序列平稳。</li>
        <li><b>MA(q) 移动平均</b>：当前值由<b>过去 q 个预测误差</b>线性组合而来（“修正过去的偏差”）。</li>
      </ul>
      <p>带季节性的扩展版本是 <b>SARIMA</b>，额外增加季节阶数 (P, D, Q, m)，m 为周期长度（如月度数据 m=12）。</p>
      <h3>核心公式（文字说明）</h3>
      <ul>
        <li><b>差分</b>：一阶差分 ∇y<sub>t</sub> = y<sub>t</sub> − y<sub>t−1</sub>（去掉趋势）；
        季节差分 = y<sub>t</sub> − y<sub>t−m</sub>（m 为周期，去掉季节性）。</li>
        <li><b>AR(p) 自回归</b>：y<sub>t</sub> = c + φ₁·y<sub>t−1</sub> + φ₂·y<sub>t−2</sub> + … + φ<sub>p</sub>·y<sub>t−p</sub> + ε<sub>t</sub>，
        即“当前值 = 常数 + 前 p 期的加权和 + 随机扰动”。</li>
        <li><b>MA(q) 移动平均</b>：y<sub>t</sub> = μ + ε<sub>t</sub> + θ₁·ε<sub>t−1</sub> + … + θ<sub>q</sub>·ε<sub>t−q</sub>，
        即“当前值 = 均值 + 当前与过去 q 期预测误差的加权和”。</li>
        <li><b>ARIMA(p, d, q)</b>：先对原序列做 d 阶差分使其平稳，再对差分后的序列拟合 ARMA(p, q)。三个参数各司其职。</li>
        <li><b>滑动窗口</b>：X<sub>t</sub> = [y<sub>t−n</sub>, …, y<sub>t−1</sub>]，目标 y<sub>t</sub>；用回归模型学习 f(X<sub>t</sub>) → y<sub>t</sub>。</li>
      </ul>
      <h3>滑动窗口方法</h3>
      <p>把时序问题<b>改造成监督学习</b>的通用技巧：用过去 <b>n</b> 个时刻的值作为特征，预测下一时刻。
      窗口在数据上一步步向后滑动，就产生大量“历史窗口 → 未来值”的训练样本。
      这样就能把随机森林、XGBoost 甚至神经网络直接用在时序预测上——
      实践中这类方法往往<b>比 ARIMA 更灵活、更能利用外部特征</b>（如节假日、促销、天气）。
      窗口内还可以构造统计特征：均值、标准差、最大值、同比/环比、滞后值（lag features）。</p>
      <h3>Python 实现</h3>
      <p><code>statsmodels</code>：<code>ADF</code> 检验、<code>seasonal_decompose</code>、<code>ARIMA</code>/<code>SARIMAX</code>、<code>plot_acf</code>/<code>plot_pacf</code>（ACF/PACF 图用于定阶 p、q）；
      <code>pmdarima.auto_arima</code> 可自动搜索最优 (p,d,q)；
      <code>sklearn.model_selection.TimeSeriesSplit</code> 做时序交叉验证；
      特征工程用 <code>pandas.shift()</code> 与 <code>rolling()</code>。</p>
      <h3>调参注意事项</h3>
      <ul>
        <li><b>先做分解与平稳化，再建模</b>：跳过这步直接拟合，模型几乎必然失效。</li>
        <li><b>定阶</b>：看 ACF 截尾定 q、PACF 截尾定 p；嫌麻烦就用 <code>auto_arima</code> 按 AIC 自动搜索。</li>
        <li><b>评估指标</b>：用 <b>MAE / RMSE / MAPE</b>，不要用准确率；且要在<b>时间上靠后的一段</b>上评估。</li>
        <li><b>基线很重要</b>：先跟“预测值 = 昨天的实际值”（朴素基线）比较，若你的模型赢不了它，说明没有真正学到东西。</li>
        <li><b>外推风险</b>：树模型（随机森林/XGBoost）无法预测超出历史范围的趋势，数据有明显增长趋势时建议先对趋势差分再建模。</li>
        <li><b>节假日/事件</b>：务必把这些已知的特殊日期作为特征加入，否则模型会把它们当成噪声。</li>
      </ul>
    `,
