    code:
`import matplotlib.pyplot as plt
from sklearn.datasets import load_iris
from sklearn.model_selection import train_test_split, cross_val_score
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import Pipeline
from sklearn.neighbors import KNeighborsClassifier
from sklearn.tree import DecisionTreeClassifier
from sklearn.svm import SVC
from sklearn.metrics import classification_report, ConfusionMatrixDisplay

# 1) 加载数据（150 条样本 × 4 个特征 × 3 个品种）
iris = load_iris()
X, y = iris.data, iris.target

# stratify=y 保证训练集和测试集中三个品种的比例一致
X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.3, random_state=42, stratify=y)

# 2) 用 Pipeline 把「标准化 + 模型」打包
#    KNN 与 SVM 都对量纲敏感，标准化是刚需
models = {
    "KNN(K=5)": Pipeline([("sc", StandardScaler()),
                          ("m", KNeighborsClassifier(n_neighbors=5))]),
    "决策树":    Pipeline([("sc", StandardScaler()),
                          ("m", DecisionTreeClassifier(max_depth=3, random_state=42))]),
    "SVM(RBF)": Pipeline([("sc", StandardScaler()),
                          ("m", SVC(kernel="rbf", C=1.0, gamma="scale", random_state=42))]),
}

# 3) 对比：交叉验证分数（更稳） + 测试集分数（最终成绩）
print(f"{'模型':<10}{'5折CV':>10}{'测试集':>10}")
for name, pipe in models.items():
    cv = cross_val_score(pipe, X_train, y_train, cv=5).mean()
    pipe.fit(X_train, y_train)
    test = pipe.score(X_test, y_test)
    print(f"{name:<10}{cv:>10.3f}{test:>10.3f}")

# 4) 细看表现最好的模型
best = models["SVM(RBF)"]
y_pred = best.predict(X_test)
print("\\nSVM 分类报告:\\n",
      classification_report(y_test, y_pred, target_names=iris.target_names))

# 5) 并排画三个混淆矩阵
fig, axes = plt.subplots(1, 3, figsize=(14, 4))
for ax, (name, pipe) in zip(axes, models.items()):
    ConfusionMatrixDisplay.from_estimator(
        pipe, X_test, y_test, display_labels=iris.target_names,
        ax=ax, cmap="Blues", colorbar=False)
    ax.set_title(name)
plt.tight_layout(); plt.show()`,
