    desc: "用 Mall Customers 数据集（年收入 × 消费评分）做客户分群：预处理 → 选 K → 聚类 → 可视化 → 商业解读。",
    code:
`import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.cluster import KMeans
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import silhouette_score

# 1) 读取数据：优先用真实的 Mall_Customers.csv，
#    若本地没有，则生成结构完全相同的模拟数据，保证代码开箱可跑
try:
    df = pd.read_csv("Mall_Customers.csv")
    df = df.rename(columns={"Annual Income (k$)": "income",
                            "Spending Score (1-100)": "score"})
    print("已加载真实数据集")
except FileNotFoundError:
    rng = np.random.default_rng(42)
    centers = np.array([[25, 20], [55, 50], [95, 80], [30, 80], [90, 20]])
    pts = np.vstack([c + rng.normal(0, 6, (40, 2)) for c in centers])
    df = pd.DataFrame(np.clip(pts, 1, 140), columns=["income", "score"])
    print("未找到 mall 数据，已生成 200 条模拟客户数据")

X = df[["income", "score"]].values

# 2) 预处理：聚类基于距离，必须标准化
scaler = StandardScaler().fit(X)
X_scaled = scaler.transform(X)

# 3) 选 K：肘部法则（SSE）+ 轮廓系数，两者一起看
ks = list(range(2, 9))
sse, sil = [], []
for k in ks:
    km = KMeans(n_clusters=k, random_state=42, n_init=10).fit(X_scaled)
    sse.append(km.inertia_)
    sil.append(silhouette_score(X_scaled, km.labels_))

fig, ax1 = plt.subplots()
ax1.plot(ks, sse, "o-", color="tab:blue", label="SSE (肘部法则)")
ax1.set_xlabel("K"); ax1.set_ylabel("SSE")
ax2 = ax1.twinx()
ax2.plot(ks, sil, "s--", color="tab:orange", label="轮廓系数")
ax2.set_ylabel("轮廓系数")
plt.title("选择 K：肘部法则 + 轮廓系数"); plt.tight_layout(); plt.show()

best_k = ks[int(np.argmax(sil))]
print("轮廓系数最高的 K =", best_k, " 对应轮廓系数 =", round(max(sil), 3))

# 4) 正式聚类
km = KMeans(n_clusters=best_k, random_state=42, n_init=10).fit(X_scaled)
df["cluster"] = km.labels_

# 5) 商业解读：每个簇的人群画像
profile = df.groupby("cluster").agg(
    客户数=("income", "size"),
    平均年收入=("income", "mean"),
    平均消费分=("score", "mean")).round(1)
print("\\n各簇画像:\\n", profile)

# 6) 可视化（质心需要逆标准化回原始坐标系）
centers_orig = scaler.inverse_transform(km.cluster_centers_)
plt.scatter(df["income"], df["score"], c=df["cluster"],
            cmap="tab10", s=35, edgecolors="k", alpha=0.85)
plt.scatter(centers_orig[:, 0], centers_orig[:, 1],
            marker="X", s=220, c="red", label="质心")
plt.xlabel("年收入 (k$)"); plt.ylabel("消费评分 (1-100)")
plt.title(f"客户分群结果 (K={best_k})")
plt.legend(); plt.tight_layout(); plt.show()`,
    steps: [
      { t: "准备数据", d: "优先读取真实的 Mall_Customers.csv；若本地没有就用相同结构生成模拟数据，保证代码随时可跑。拿到真实数据只需把 CSV 放到同目录。" },
      { t: "标准化", d: "K-Means 完全基于距离。年收入以千美元计、消费评分是 1–100，量纲不一致会让收入完全主导结果，StandardScaler 是刚需。" },
      { t: "用两种方法选 K", d: "肘部法则看 SSE 的下降拐点，轮廓系数看「簇内紧密、簇间分离」的程度（越接近 1 越好）。两者结论不一致时，优先参考轮廓系数并结合业务。" },
      { t: "正式聚类", d: "n_init=10 表示用 10 组不同初始质心各跑一遍取最优，规避 K-Means 对初始化敏感的问题；random_state 保证结果可复现。" },
      { t: "商业解读（最关键的一步）", d: "聚类本身没有意义，给每个簇贴上业务标签才有价值：例如「高收入高消费=VIP 客户」「低收入高消费=潜力年轻客群」「高收入低消费=待激活客户」。" },
      { t: "可视化并还原质心", d: "质心是在标准化空间里算出来的，必须用 scaler.inverse_transform 还原回「年收入 × 消费评分」的原始坐标系，否则画出来的位置是错的。" },
    ],
    explain: `
      <h4>怎么读这两张曲线</h4>
      <ul>
        <li><b>SSE</b>：随 K 增大必然下降，取“收益递减”的拐点（像手肘）。缺点是拐点常常不明显。</li>
        <li><b>轮廓系数</b>：取值 −1~1，<b>越接近 1 越好</b>。它同时衡量簇内紧密度与簇间分离度，通常比肘部法则更客观。</li>
      </ul>
      <h4>从结果到决策</h4>
      <p>拿到簇画像后，业务动作才真正开始：VIP 客群做会员权益、潜力客群做交叉销售、待激活客群做唤醒营销。
      <b>聚类的价值不在算法，而在你给每个簇讲出的故事。</b></p>
    `,
