      "关键超参数：max_depth 限深度、min_samples_split/min_samples_leaf 限最小样本数、max_features 限每次考虑的特征数",
      "优点：几乎不需要预处理（不用标准化）、能处理非线性关系、可直接看特征重要性 feature_importances_",
      "缺点：不剪枝的树极易过拟合，且对训练样本扰动敏感",
