    answer: "决策树在 sklearn 里就是 fit / predict 两步，但真正决定效果好坏的是超参数：不设限制的树会长到每个叶子只剩一个样本，必然过拟合。实战中至少要把 max_depth 和 min_samples_leaf 设上，并用交叉验证挑值。训练完还能直接看 feature_importances_ 判断哪些特征最关键。",
