      "清洗：dropna / fillna 处理缺失，drop_duplicates 去重复，astype 转类型，pd.to_datetime 转日期",
      "聚合：groupby('类别')['金额'].agg(['mean','count']) 是最常用的统计姿势",
      "输出：df.to_csv('out.csv', index=False) —— 记得加 index=False，否则会多出一列索引",
