      "阶段三（2~3 周）：模型优化——特征工程、正则化、超参数调优、集成学习（随机森林、XGBoost）",
      "阶段四（2~3 周）：无监督与降维——K-Means、DBSCAN、层次聚类、PCA",
      "阶段五（4 周+）：深度学习——神经网络基础、PyTorch、CNN（图像）、RNN/Transformer（文本）",
      "贯穿全程：每学一个算法就问自己三个问题——它假设什么、什么时候会失效、怎么判断它失效了",
