      "先记住 sklearn 的统一接口：fit 训练、predict 预测、score 评估——所有模型都一样，学会一个就会一片",
      "边做边补理论：遇到“为什么准确率只有 60%”再去学过拟合、学特征工程，带着问题学记得最牢",
