      "微积分与优化：导数、偏导、链式法则、梯度——对应梯度下降与反向传播，看懂神经网络的必备",
      "信息论入门：熵、交叉熵、KL 散度——对应决策树的划分准则与分类损失函数",
      "优先级建议：先线性代数 → 再概率统计 → 最后微积分；配合 3Blue1Brown《线性代数的本质》等可视化资料效率高很多",
      "现实一点：日常调包建模 80% 的时间不推导公式，数学主要在你“想改模型、想看懂论文”时才变得关键",
